-- cpd-migration: additive
-- A Plan review's own title (contract §2.2 Plan review; hs-d291): nullable, because a
-- review requested before this migration has none. One line, 1-72 characters
-- and no control characters are checked at the boundary (`PrTitle`) and here.
-- The history triggers of `plan_reviews` are regenerated by the runner's reconcile.
ALTER TABLE plan_reviews ADD COLUMN title TEXT CHECK (title IS NULL OR length(title) BETWEEN 1 AND 72);
